{
    m_agent_pane_user_collapsed = false;
    if (m_tabpanel->GetSelection() == MainFrame::tpHome)
        m_frame->select_tab(size_t(MainFrame::tp3DEditor));
    set_agent_pane_collapsed(false);
    m_agent_pane->web_view().host().request_setup();
